#!/usr/bin/env node
// Generates the React icon components from the committed Figma icon snapshot (icons/figma-icons.json).
//
//   node build-icons.mjs [--check]
//
// Writes, for the app and for the component templates:
//   components/icons/figma.tsx    one component per Figma icon: "angle-down" → AngleDownIcon (generated, never edit)
//   components/icons/catalog.ts   name, group and component of every icon, for the Storybook icon gallery
// The hand-written createIcon.tsx and index.ts next to them hold the shared <svg> behaviour and the exports.
// --check: exit 1 when a generated file differs from a fresh build.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const skill = path.resolve(here, '..');
const root = path.resolve(skill, '../../..');
const snapshot = JSON.parse(fs.readFileSync(path.join(skill, 'icons/figma-icons.json'), 'utf8'));
const targets = [path.join(root, 'src/components/icons'), path.join(skill, 'templates/icons')];
const check = process.argv.includes('--check');

const pascal = (name) => name.split(/[^a-zA-Z0-9]+/).filter(Boolean).map((p) => p[0].toUpperCase() + p.slice(1)).join('');
// SVG attribute → JSX prop: fill-rule → fillRule, xlink:href → xlinkHref.
const jsx = (body) =>
  body
    .replace(/\s([a-z]+(?:[-:][a-z]+)+)=/g, (_, a) => ' ' + a.replace(/[-:]([a-z])/g, (__, c) => c.toUpperCase()) + '=')
    .replace(/\/>/g, ' />');

const names = new Set();
const lines = [];
for (const icon of snapshot.icons) {
  const comp = pascal(icon.name) + 'Icon';
  if (names.has(comp)) throw new Error(`Two icons map to ${comp}`);
  names.add(comp);
  lines.push(`/** Figma “${icon.figmaName}” (${icon.group}) */\nexport const ${comp} = /* @__PURE__ */ createIcon('${icon.name}', '${icon.viewBox}', <>${jsx(icon.body)}</>);`);
}
const header = `// Generated by .claude/skills/ad-design-kit-design-system/scripts/build-icons.mjs from the Figma Icons page
// (snapshot icons/figma-icons.json, ${snapshot.icons.length} icons). Do not edit: re-sync from Figma instead.
// ad-design-kit-lint-ignore-file: icon names such as "text-size" are not classes.\n`;
const figma = `${header}import { createIcon } from './createIcon';\n\n${lines.join('\n\n')}\n`;
const catalog = `${header}import type { ComponentType } from 'react';
import type { IconProps } from './createIcon';
import * as Icons from './figma';

export interface IconEntry { name: string; group: string; component: string; Icon: ComponentType<IconProps> }

export const iconCatalog: IconEntry[] = [
${snapshot.icons.map((i) => `  { name: '${i.name}', group: '${i.group}', component: '${pascal(i.name)}Icon', Icon: Icons.${pascal(i.name)}Icon },`).join('\n')}
];
`;

let stale = false;
for (const dir of targets) {
  for (const [file, content] of [['figma.tsx', figma], ['catalog.ts', catalog]]) {
    const p = path.join(dir, file);
    if (check) { if (!fs.existsSync(p) || fs.readFileSync(p, 'utf8') !== content) { stale = true; console.error(`stale: ${path.relative(root, p)}`); } continue; }
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(p, content);
  }
}
if (check) {
  if (stale) { console.error('Icon components are stale: run npm run icons:build'); process.exit(1); }
  console.log(`${snapshot.icons.length} icons · up to date`);
} else console.log(`Wrote ${snapshot.icons.length} icon components to ${targets.map((t) => path.relative(root, t)).join(' and ')}`);
